// Watchlist: newline- or comma-separated queries in the FINSIGHT_WATCHLIST
// env var (set in docker-compose .env), else this default list.
const raw = ($env.FINSIGHT_WATCHLIST || '').trim();
const defaults = [
  'Is KPIT Technologies a good stock to hold right now?',
  'Any notable movement or news in Reliance Industries?',
  'How is Infosys looking on fundamentals this quarter?',
];
const queries = raw
  ? raw.split(/[\n,]/).map((s) => s.trim()).filter(Boolean)
  : defaults;
return queries.map((q) => ({ json: { query: q } }));

// Fold every /research response into ONE Slack message.
const tz = $env.GENERIC_TIMEZONE || 'Asia/Kolkata';
const date = new Date().toLocaleDateString('en-IN', { timeZone: tz, dateStyle: 'medium' });
const queries = $('Build watchlist').all().map((i) => i.json.query);

const sections = $input.all().map(({ json }, idx) => {
  const q = json.query || queries[idx] || '(unknown query)';
  if (!json.report) {
    const err = (json.error && (json.error.message || json.error)) || 'no report returned';
    return `*${q}*\n_error: ${err}_`;
  }
  const tag = json.in_coverage ? (json.ticker || '') : 'not in coverage';
  let body = json.report;
  const m = body.match(/##\s*Executive Summary\s*\n+([\s\S]*?)(\n##\s|\n---|\s*$)/i);
  if (m) body = m[1].trim();
  if (body.length > 700) body = body.slice(0, 700).trimEnd() + '…';
  return `*${q}*${tag ? ` (${tag})` : ''}\n${body}`;
});

const text = `*FinSight Daily Brief — ${date}*\n\n` +
  sections.join('\n\n———\n\n') +
  `\n\n_Educational demo, not financial advice._`;
return [{ json: { text } }];
